import psutil

# Common mining pool / miner-related ports. Not exhaustive.
SUSPICIOUS_PORTS = {
    3333, 4444, 5555, 7777, 8333, 9999, 14444, 45700
}

# Common miner process name fragments. Not exhaustive.
SUSPICIOUS_NAMES = {
    "xmrig", "minerd", "cpuminer", "cgminer", "bfgminer",
    "ethminer", "nbminer", "lolminer", "t-rex", "phoenixminer",
    "kawpowminer", "teamredminer", "srbminer"
}

CPU_THRESHOLD = 70.0  # percent
CHECK_INTERVAL = 10   # seconds

def process_name(proc):
    try:
        return (proc.name() or "").lower()
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        return ""

def check_processes():
    alerts = []
    for proc in psutil.process_iter(["pid", "name", "cpu_percent", "username"]):
        try:
            info = proc.info
            name = (info.get("name") or "").lower()
            cpu = info.get("cpu_percent") or 0.0

            if any(frag in name for frag in SUSPICIOUS_NAMES):
                alerts.append(
                    f"[NAME] pid={info['pid']} user={info.get('username')} "
                    f"name={info.get('name')} cpu={cpu:.1f}%"
